// Derived from pybind's string_caster in cast.h, but allows transacting None with nullptr since Carbonite strings
// support that.
template <typename StringType, bool IsView = false>
struct string_caster_allow_none : string_caster<StringType, IsView>
{
    using CharT = typename StringType::value_type;
    using BaseClass = string_caster<StringType, IsView>;
    bool none{ false };

    bool load(handle src, bool convert)
    {
        if (!src)
            return false;
        if (src.is_none())
        {
            if (!convert)
                return false;
            none = true;
            return true;
        }
        return BaseClass::load(src, convert);
    }

    using BaseClass::cast;
    static handle cast(const StringType& src, return_value_policy policy, handle parent)
    {
        if constexpr (std::is_convertible_v<decltype(src), bool>)
        {
            if (!src)
                return pybind11::none().release();
        }
        if constexpr (std::is_pointer_v<decltype(src.data())>)
        {
            if (!src.data())
                return pybind11::none().release();
        }
        return BaseClass::cast(src, policy, parent);
    }

    explicit operator StringType*()
    {
        return none ? nullptr : std::addressof(this->value);
    }
    explicit operator StringType&()
    {
        if (none)
            this->value = {};
        return this->value;
    }
    explicit operator StringType&&() &&
    {
        if (none)
            this->value = {};
        return std::move(this->value);
    }
};

//! Converts between @c omni::string and native Python @c `str` types.
template <>
struct type_caster<omni::string> : string_caster_allow_none<omni::string>
{
};

//! Convert between @c carb::cpp::basic_string_view types and native Python `str` types
template <class CharT, class Traits>
struct type_caster<carb::cpp::basic_string_view<CharT, Traits>>
    : string_caster_allow_none<carb::cpp::basic_string_view<CharT, Traits>, true /* life support */>
{
};

//! Convert between @c carb::cpp::basic_zstring_view types and native Python `str` types
template <class CharT, class Traits>
struct type_caster<carb::cpp::basic_zstring_view<CharT, Traits>>
    : string_caster_allow_none<carb::cpp::basic_zstring_view<CharT, Traits>, true /* life support */>
{
};

template <class CharT>
struct type_caster<carb::cpp::basic_unbounded_string<CharT>>
{
    using SelfType = carb::cpp::basic_unbounded_string<CharT>;
    using ContainerType = carb::cpp::basic_zstring_view<CharT>;
    using StringCaster = make_caster<ContainerType>;
    StringCaster str_caster;
    SelfType value;
    bool none = false;

    bool load(handle src, bool convert)
    {
        if (!src)
            return false;
        if (src.is_none())
        {
            if (!convert)
                return false;
            none = true;
            return true;
        }
        return str_caster.load(src, convert);
    }

    static handle cast(const SelfType& src, return_value_policy policy, handle parent)
    {
        if (!src)
            return pybind11::none().release();
        return StringCaster::cast(ContainerType(carb::cpp::unsafe_length, src), policy, parent);
    }

    explicit operator SelfType*()
    {
        value = static_cast<ContainerType&>(str_caster).c_str();
        return none ? nullptr : &value;
    }
    explicit operator SelfType&()
    {
        value = none ? (const char*)nullptr : static_cast<ContainerType&>(str_caster).c_str();
        return value;
    }

    static constexpr auto name = const_name(PYBIND11_STRING_NAME);
    template <typename U>
    using cast_op_type = pybind11::detail::cast_op_type<U>;
};

template <class T>
struct type_caster<carb::cpp::optional<T>> : optional_caster<carb::cpp::optional<T>>
{
};

